function Write-Icons($dir, $color) {
    if (Test-Path $dir) { Remove-Item -Recurse -Force $dir }
    New-Item -ItemType Directory -Path $dir | Out-Null
    foreach ($name in $icons.Keys) {
        $path = Join-Path $dir ($name + '.svg')
        $svg = "<?xml version=""1.0"" encoding=""UTF-8""?>`n" +
               "<svg xmlns=""http://www.w3.org/2000/svg"" width=""24"" height=""24"" viewBox=""0 0 24 24"">`n" +
               "  <path fill=""$color"" d=""$($icons[$name])""/>`n" +
               "</svg>`n"
        [System.IO.File]::WriteAllText($path, $svg)
    }
}

Write-Icons 'qml\tieba\icons\light' '#5f6368'
Write-Icons 'qml\tieba\icons\dark'  '#e8eaed'
Write-Output ("Generated {0} icons x 2 variants" -f $icons.Count)

